sys_generative_ai_custom_llm_transformer.request_transformer:
(function(inputs) {
    var requestData = inputs.request_data;
    var promptData = inputs.prompt_data;
    var prompt = promptData.prompt;

    var body = {
        model: "claude-sonnet-4-5",
        max_tokens: 700,
        messages: [{
            "role": "user",
            "content": prompt
        }]
    };

    var headers = {
        "x-api-key": "",
        "anthropic-version": "2023-06-01"
    };

    return {
        body: body,
        headers: headers
    };
})(inputs);

sys_generative_ai_custom_llm_transformer.response_transformer:
(function(inputs) {
    var requestData = inputs.request_data;
    var promptData = inputs.prompt_data;
    var responseBody = JSON.parse(inputs.response_body);

    var responseTexts = [];
    responseTexts.push(responseBody.content[0].text);

    return responseTexts;
})(inputs);
